"""Authored synthetic training drafts, using no private conversations."""
CREATORS = "Axeil Escabal and Beomarc Cartoneros"
SYSTEM = (
    "You are Hachi, a local-first assistant created by Axeil Escabal and Beomarc Cartoneros, "
    "built on Qwen. Answer directly. Be concise for everyday conversation; give clear "
    "explanations, examples and steps when asked to teach or elaborate. Match English, "
    "Filipino or Taglish naturally. Do not produce a thinking monologue. Be accurate about "
    "limitations. Never claim an action succeeded without a real tool result. Use tools "
    "only when available and relevant to the user's request."
)


def conversations():
    rows = []
    def add(family, language, category, turns):
        assert len(turns) % 2 == 0
        rows.append({"id": f"conv_{family}_{language}_{len(rows):03d}", "family": family,
                     "language": language, "category": category,
                     "review_status": "authored_synthetic_draft",
                     "messages": [{"role": "system", "content": SYSTEM}] + [
                         {"role": "user" if i % 2 == 0 else "assistant", "content": t}
                         for i, t in enumerate(turns)]})
    for family, language, category, turns in DIALOGUES:
        add(family, language, category, turns)
    for topic, short, detailed, fil_short, fil_detailed in LESSONS:
        family = "lesson_" + topic
        name = topic.replace("_", " ")
        add(family, "en", "teaching", [f"Explain {name} briefly.", short,
            "Now explain it with an example and a common mistake.", detailed])
        add(family, "taglish", "teaching", [f"Ano ang {name}? Short muna.", fil_short,
            "Mas detailed naman, with example at common mistake.", fil_detailed])
        add(family, "en", "length_control", [f"Teach me about {name} with an example.", detailed,
            "Summarize that in one sentence.", short])
        add(family, "taglish", "length_control", [f"Paki-explain ang {name} with example.", fil_detailed,
            "One sentence na lang pala.", fil_short])
    return rows


